# ABOUTME: Runs and inspects the local runtime assigned to a managed worktree.
# ABOUTME: Reads only .worktree.json, which is generated by new-session.ps1.

param(
    [Parameter(Position = 0)]
    [ValidateSet("dev", "status", "finish")]
    [string]$Command = "status"
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$rootDir = Split-Path $PSScriptRoot -Parent
$metadataPath = Join-Path $rootDir ".worktree.json"

if (-not (Test-Path -LiteralPath $metadataPath)) {
    throw "This directory is not a managed worktree. Create it with scripts/new-session.ps1."
}

$metadata = Get-Content -LiteralPath $metadataPath -Raw | ConvertFrom-Json
$currentRoot = (& git rev-parse --show-toplevel).Trim()
if ($LASTEXITCODE -ne 0) {
    throw "Current directory is not a Git worktree."
}

function Show-Status {
    $branch = (& git branch --show-current).Trim()
    $changes = & git status --short

    Write-Host "Worktree : $currentRoot"
    Write-Host "Branch    : $branch"
    Write-Host "Base      : $($metadata.baseRef) @ $($metadata.baseCommit)"
    Write-Host "URL       : $($metadata.url)"
    Write-Host "DB name   : $($metadata.databaseName)"

    if ($branch -ne $metadata.branch) {
        Write-Warning "This worktree is checked out on '$branch', expected '$($metadata.branch)'."
    }

    if ($changes) {
        Write-Warning "Uncommitted changes:"
        $changes
    }
    else {
        Write-Host "Changes   : clean"
    }
}

switch ($Command) {
    "status" {
        Show-Status
    }
    "dev" {
        $envPath = Join-Path $rootDir ".env.local"
        if (-not (Test-Path -LiteralPath $envPath)) {
            throw "Missing $envPath. Recreate this worktree with scripts/new-session.ps1."
        }

        Write-Host "Starting $($metadata.url) ..."
        & npm.cmd run dev -- --port $metadata.port
        exit $LASTEXITCODE
    }
    "finish" {
        Show-Status
        Write-Host ""
        Write-Host "Before opening a PR:"
        Write-Host "  git fetch origin main"
        Write-Host "  git rebase origin/main"
        Write-Host "  npm run lint"
        Write-Host "  npm test"
        Write-Host "  git push -u origin $($metadata.branch)"
        Write-Host ""
        Write-Host "Remove this worktree only after the PR is merged or explicitly abandoned."
    }
}
